def table(headers, rows, cls=''):
    return f'<table class="{cls}"><thead><tr>'+''.join(f'<th>{html.escape(v)}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{html.escape(v)}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'

def card(title, body, cls=''):
    return f'<div class="card {cls}"><h3>{title}</h3>{body}</div>'

def page(num,title,subtitle,body):
    return f'<section class="page" id="p{num}"><header><div class="eyebrow">LISHUI JIAYUAN / 丽水嘉园 · 176㎡</div><span>概念深化 · R6 岛桌相连 / 保留燃气 · 2026.09.08</span></header><h1><b>{num}</b>{title}</h1><p class="subtitle">{subtitle}</p>{body}<footer><span>依据用户方案、新图及墙体图例｜176㎡为任务提供面积，非净面积测算</span><span>未实测 · 非施工图　/　{num}</span></footer></section>'

